  "command": "cat > /workspace/dev_tests/watch.py <<'EOF'
import json, time
from research_sdk import Client
c = Client()
ids = {'dev01':'ee7f0bc2159c441680be63646b69c0d6','dev06':'7b52c7c3efcf404385e9dd5dd697b989',
       'dev08':'a2af02eef1e545549f8e2e2208c23785','dev12':'797e54a95e174e4383d3c0e11e0622fb'}
for i in range(60):
    done = True
    out = {}
    for k,jid in ids.items():
        r = c.status(jid)
        st = r.get('status')
        out[k] = (st, r.get('cost',{}).get('charged_usd'))
        if st not in ('ok','failed','cancelled'):
            done = False
    print(json.dumps(out), flush=True)
    if done:
        break
    time.sleep(30)
json.dump({'ids':ids}, open('/workspace/dev_tests/final_ids.json','w'))
print("ALL DONE", flush=True)
EOF
python3 dev_tests/watch.py > /workspace/dev_tests/watch.log 2>&1 &
echo "watcher started pid $!"",
  "description": "Start background watcher"
}

